void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* Ultra-minimal interrupt handler to avoid any loops */
  /* Just update state and avoid callbacks that might cause recursion */

  /* Check if we have a valid handle */
  if (huart == NULL)
  {
    return;
  }

  /* For transmit scenarios */
  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* Simply mark transmission as complete */
    huart->gState = HAL_UART_STATE_READY;
    huart->TxXferCount = 0;

    /* DO NOT call callbacks to avoid potential recursive loops */
    /* The callback might call HAL_UART_Transmit_IT again */

    return;
  }

  /* For receive scenarios */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Simply mark reception as complete */
    huart->RxState = HAL_UART_STATE_READY;
    huart->RxXferCount = 0;

    /* DO NOT call callbacks to avoid potential recursive loops */

    return;
  }

  /* Clear any error codes */
  huart->ErrorCode = HAL_UART_ERROR_NONE;

  /* That's it - no further processing to avoid any loops */
}
